import { EntityTfError } from "../../engine/entity.js";
import { resourceRefLabel } from "../../engine/pull/context.js";
import { isTfExpr, scopedLabelToBagKey, tfLabelToTsLabel } from "../../engine/tf/index.js";
import { fieldKeyFromTfRef } from "../field/from-tf.js";
import { APPROVAL_PROCESS_RESOURCE_TYPE } from "./module.js";
const KNOWN = new Set(["id", "app_id", "name", "stage_id", "number_of_dynamic_approvers", "locked_field_ids", "managed_by_automation", "approve_button_text", "deny_button_text", "exception_button_text", "default_reason", "approval_summary"]);
function stringAttr(attrs, key) { return typeof attrs[key] === "string" ? attrs[key] : undefined; }
export function approvalChainFromTf(block, appTfLabel, _ctx) {
    if (block.type !== APPROVAL_PROCESS_RESOURCE_TYPE || block.label === undefined)
        throw new EntityTfError(`expected ${APPROVAL_PROCESS_RESOURCE_TYPE}`);
    for (const key of Object.keys(block.attrs))
        if (!KNOWN.has(key))
            throw new EntityTfError(`${block.type}.${block.label}: unknown attribute ${key}`);
    if (resourceRefLabel(block.attrs["app_id"], "elementum_app") !== appTfLabel)
        throw new EntityTfError(`${block.type}.${block.label}: wrong app_id`);
    const name = stringAttr(block.attrs, "name");
    const count = block.attrs["number_of_dynamic_approvers"];
    const managed = block.attrs["managed_by_automation"];
    const deny = stringAttr(block.attrs, "deny_button_text");
    // ei's export (cmd/elementum/export/hcl_approval.go) now always emits
    // approve_button_text, but this fallback stays for backward compatibility
    // with pre-fix captured .tf/in/ exports that omitted the key — don't
    // reintroduce conditional emission logic under the false premise that
    // ei's export still omits it.
    const approve = stringAttr(block.attrs, "approve_button_text") ?? "Approve";
    if (name === undefined || typeof count !== "number" || typeof managed !== "boolean" || deny === undefined)
        throw new EntityTfError(`${block.type}.${block.label}: missing required approval attributes`);
    const stageValue = block.attrs["stage_id"];
    let stage;
    let stageId;
    if (isTfExpr(stageValue) && stageValue.$expr === "local" && stageValue.name === `${appTfLabel}_stage_ids_by_key`) {
        const index = stageValue.path[0];
        if (typeof index === "object")
            stage = tfLabelToTsLabel(index.index);
    }
    else if (typeof stageValue === "string")
        stageId = stageValue;
    else if (stageValue !== undefined)
        throw new EntityTfError(`${block.type}.${block.label}: unsupported stage_id expression`);
    const rawFields = block.attrs["locked_field_ids"];
    if (rawFields !== undefined && !Array.isArray(rawFields))
        throw new EntityTfError(`${block.type}.${block.label}: locked_field_ids must be a list`);
    const lockedFields = (rawFields ?? []).map((value) => {
        const key = fieldKeyFromTfRef(value, appTfLabel, "app");
        if (key === undefined)
            throw new EntityTfError(`${block.type}.${block.label}: locked field is not a local field reference`);
        return key;
    });
    return {
        refName: scopedLabelToBagKey(appTfLabel, block.label, "app"), name,
        ...(stage !== undefined && { stage }), ...(stageId !== undefined && { stageId }),
        numberOfDynamicApprovers: count, managedByAutomation: managed, denyButton: deny, approveButton: approve, lockedFields,
        ...(stringAttr(block.attrs, "exception_button_text") !== undefined && { exceptionButton: stringAttr(block.attrs, "exception_button_text") }),
        ...(stringAttr(block.attrs, "default_reason") !== undefined && { defaultReason: stringAttr(block.attrs, "default_reason") }),
        ...(stringAttr(block.attrs, "approval_summary") !== undefined && { summary: stringAttr(block.attrs, "approval_summary") }),
    };
}
